using Microsoft.EntityFrameworkCore;

// Cosmos DB project context with EF Core 9 breaking change mitigations
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // EF Core 9 Breaking Change: discriminator property renamed from "Discriminator" to "$type".
            // Existing documents use "Discriminator", so explicitly preserve the old name.
            b.HasDiscriminator<string>("Discriminator");

            // EF Core 9 Breaking Change: id property no longer includes discriminator prefix.
            // Existing documents have "Session|<key>" format; preserve old compound id format.
            b.HasRootDiscriminatorInJsonId(true);
        });
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Title { get; set; } = default!;
    public DateTime StartedAt { get; set; }
}

// EF Core 9 Breaking Change: Cosmos DB provider no longer supports synchronous I/O.
// All sync calls (ToList, SaveChanges, First, etc.) now throw.
// Convert to async equivalents (ToListAsync, SaveChangesAsync, FirstAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 — sync was allowed):
    //   var sessions = _db.Sessions.Where(s => s.StartedAt > cutoff).ToList();
    //   _db.Sessions.Add(new Session { ... });
    //   _db.SaveChanges();

    // AFTER (EF Core 9 — must use async):
    public async Task<List<Session>> GetRecentSessionsAsync(DateTime cutoff)
    {
        return await _db.Sessions
            .Where(s => s.StartedAt > cutoff)
            .ToListAsync();
    }

    public async Task AddSessionAsync(Session session)
    {
        _db.Sessions.Add(session);
        await _db.SaveChangesAsync();
    }
}

